  ["ca0a0118f94c439e"] = { "Grazie della visita, {class}. Ora abbiamo tutti i Lingotti di Torio che ci servono, ma potresti chiedere ad alcuni degli altri qui che si occupano di altre raccolte.", "." },
  ["ca0eede35154bea5"] = { "Sì, Augustus. Vorrei fare affari.", "." },
