  ["ca1671f7ce00330c"] = { "%s cinguetta un saluto a {name}.", "." },
  ["ca18970976f321c8"] = { "Fa sempre piacere quando qualcuno vuole parlarmi. Come va, {class}?", "." },
  ["ca226d0b1e19d3b6"] = { "Non vacillare, campione. So perché sei qui e so cosa cerchi. Eranikus non cederà il frammento di sua volontà. È stato corrotto... corrotto dalla stessa forza che cerchi di distruggere.", "." },
  ["ca2abbd13bd5c8d0"] = { "Da grande voglio regnare su ⟦Stormwind=Roccavento⟧!", "." },
  ["ca2b3cd2b577b5c7"] = { "I goblin vincono la gara di velocità! Più fortuna la prossima volta, squadra degli gnomi.", "." },
  ["ca2b91ab263fbf4a"] = { "Siamo qui per fare profitto. E farsi rubare la merce non è certo il modo per fare profitto.", "." },
  ["ca352652fc77c931"] = { "%s posa un impiastro sulla fronte di Relara.", "." },
  ["ca41bb8193ea14f0"] = { "Tornate dal vostro Re dei Lich, creature immonde!", "." },
  ["ca43a107b14307db"] = { "Sono fuori dalla pancia di questa bestia da nemmeno due minuti e qualcuno mi chiede già delle mie abitudini in bagno??? <Signorino/Signorina>, ti avrei preso a schiaffi per una domanda simile, se non fosse che mi hai appena salvato la vita!\n\nComunque! Grazie per l'aiuto. Magari posso ricambiare?", "." },
  ["ca43a25196eca59c"] = { "Ooh!...Ooh!...Ahh! C'è mancato poco. Ops!...Oh, che dolore, caro ragazzo, che dolore!", "." },
  ["ca4796a66fad9fa3"] = { "Mi servono un paio di bravi gregari per uscire da qui senza rischi e tornare alla base.", "." },
  ["ca487f777d530df0"] = { "Questo dovrebbe fare il suo dovere per bene...", "." },
  ["ca4b20dab4c9e750"] = { "AHI! Così non va!", "." },
  ["ca502501d9418f09"] = { "Ehi, Pratt, puoi insegnarmi a fare un ⟦Wild Leather Cloak=Mantello di Cuoio Selvatico⟧?", "." },
  ["ca506da805d3417b"] = { "Salute, {race}. Il materiale bellico è in viaggio e dovrebbe arrivare alla ⟦Cenarion Hold=Fortezza Cenariana⟧ entro un giorno. Possiamo solo sperare che, una volta lì, qualcuno, dopo aver ricomposto lo Scettro delle Sabbie Mutevoli, si faccia avanti per suonare il gong e aprire i cancelli.", "." },
  ["ca52fba6e1b37752"] = { "Ah! Eccolo.", "." },
  ["ca60a30e0e6f149f"] = { "Salute, {name}. Hai scoperto qualcosa di nuovo sui piani e le operazioni della S.P.R. & Co. nella nostra terra?\n\nSe intendono sfruttare le nostre terre come hanno fatto con altre, gli Outrunner non ci metteranno molto a porvi fine.", "." },
  ["ca6ff14700ce168e"] = { "Va bene! Va bene! Ci arrendiamo... Abbassate le armi, collaborerò!", "." },
  ["ca71b8a5ced3b2d3"] = { "Che i tuoi anziani ti benedicano, {name}, e ti portino fortuna nell'anno che verrà.", "." },
  ["ca73de4a58b7f38b"] = { "Piacere di conoscerti! Se ti piace armeggiare con i congegni, sei nel posto giusto!", "." },
  ["ca7d815d670ae7ea"] = { "Se vuoi diventare <un/una> <paladino/paladina> possente, non c'è maestro migliore di lord Grayson Shadowbreaker. Lo troverai nella ⟦Cathedral of Light=Cattedrale della Luce⟧, in Cathedral Square.", "." },
  ["ca8161125ae7fa78"] = { "Una fiamma incandescente si accende nella coppa quando vi deponi la brace. Senti gli effetti magici della sapta scorrerti nel corpo, e il fuoco danza ritmicamente davanti a te.\n\nPosi la cima della torcia nel bacile, e questa prende subito fuoco.", "." },
  ["ca820b23db15e805"] = { "Muori, {race}! Queste terre appartengono alla tribù Scheggiadura!", "." },
  ["ca856c88f471610b"] = { "Che succede?", "." },
  ["ca85db72b95da49f"] = { "Le tue abilità stanno diventando davvero straordinarie. Ora continuiamo il tuo addestramento...", "." },
  ["ca8a0d423ba2b333"] = { "Sia lodata Elune! Non so se ce l'avrei fatta a superare questa giornata senza di te, amico.", "." },
  ["ca93a585590a00d3"] = { "Fallo e basta, lurido {race}.\n\n<Kharan abbassa la testa, scoprendo il collo tozzo.>", "." },
  ["ca9ab18f1492f88b"] = { "Vuoi farmi del male, {race}?", "." },
  ["ca9e5f3843c55267"] = { "⟦Tower Point=Torre Granguardia⟧ Est presidia il passo tra il ⟦Field of Strife=Pian della Discordia⟧ e i territori dell'⟦Horde=Orda⟧ a sud.\n\nÈ sotto il controllo dell'⟦Horde=Orda⟧.La East Frostwolf Tower protegge la porta tra il ⟦Frostwolf Village=Villaggio dei Lupi Bianchi⟧ e la ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧.\n\nÈ sotto il controllo dell'⟦Horde=Orda⟧.", "." },
  ["caa43405850da915"] = { "Ho perso la mia ⟦Scythe of the Unseen Path=Falce del Sentiero Invisibile⟧. Puoi sostituirmela?", "." },
  ["caab579f6374c3ab"] = { "Adesso le prendi di santa ragione, {name}!", "." },
  ["caacdac6b93d0186"] = { "Arrivano le bestie!", "." },
  ["caadd0f5a1ad94f3"] = { "ha un'aria molto assonnata...", "." },
  ["caae3bd4e14dcec7"] = { "Barnil, mi sa che ho perso il Capitolo III.", "." },
  ["cabe4634ab543a45"] = { "%s arriva!", "." },
  ["cabf7d5cea318e1a"] = { "Per Orgrim! Questo indurio resiste a un calore enorme!", "." },
  ["cac0ba34d8e16695"] = { "Sei <pronto/pronta> per cose più grandi! Va' da Franklin Lloyd, alla mia destra. D'ora in poi sarà lui a guidarti.", "." },
  ["cac9143ba7d1e81d"] = { "Benvenuto al ⟦Revantusk Village=Villaggio degli Zannatorta⟧, straniero. Sono il primordiale Torntusk, capo dei troll Zannatorta.", "." },
  ["cacae57f231b9068"] = { "Poi non devi far altro che sederti vicino al fuoco e goderti il calore. Dopo qualche minuto di riposo otterrai vari benefici che ti aiuteranno nei tuoi viaggi.", "." },
  ["cacdba3723384300"] = { "Torna qui, Fluffy!", "." },
  ["caea5799997e5cf5"] = { "Certamente, <signore/signorina>. Un tempo eravamo servitori della casata Barov: quella che oggi è nota come Scholomance.\n\nIo ero la governante e Lucien era il maggiordomo di padron Barov.\n\nAvevamo lavorato per i Barov per decenni, finché...\n\n<Eva piange.>", "." },
  ["caea9833c6b48dfc"] = { "Non merito tanto, <signore/signora>.", "." },
